def import_conferences(apps, schema_editor):
    Event = apps.get_model('webkato', 'Event')
    tz = pytz.timezone('Asia/Almaty')

    # Remove duplicates and non-Kazakhstan events from archive
    Event.objects.filter(slug__in=['conf-2021-20th', 'conf-2026', 'webinar-errors-replacement', 'foot-surgery-masterclass', 'trauma-2025']).delete()

    # Mark APOA 2027 as international
    Event.objects.filter(slug='apoa-2027').update(is_international=True)

    for item in CONFERENCES_DATA:
        dt = tz.localize(datetime.datetime.strptime(item["date"], "%Y-%m-%d %H:%M:%S"))
        pdf_path = f"events/programs/{item['target_file']}"

        Event.objects.update_or_create(
            slug=item["slug"],
            defaults={
                'title': item["title"],
                'date': dt,
                'date_text': item["date_text"],
                'location': item["location"],
                'description': item["desc"],
                'program_pdf': pdf_path,
                'is_active': False,
                'is_international': False,
            }
        )

